self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;const known=FILES.some(p=>new URL(p,self.registration.scope).pathname===u.pathname);if(!known&&event.request.mode!=='navigate')return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&!response.redirected){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(event.request,copy)))}return response}).catch(async()=>{const cache=await caches.open(CACHE),hit=await cache.match(event.request)||await cache.match(new URL(u.pathname,u.origin));if(hit)return hit;if(event.request.mode==='navigate')return(await cache.match('./'))||Response.error();return Response.error()}))});
